import jax
import jax.numpy as jnp
from jax import random
from functools import partial   # used in _flash_attn, blockwise

# %% ../nbs/01_nn.ipynb #66d9c99e
def split_key(key, n):
    "Split `key` into `n` keys, or return `n` Nones in eval mode."
    return random.split(key, n) if key is not None else (None,) * n

# %% ../nbs/01_nn.ipynb #de139071
def make_dropout(key, rate=0.0, broadcast_dims=()):
    "Inverted dropout. `broadcast_dims` share one mask value along those axes (e.g. (2, 3) for NCHW channel dropout)."
    def dropout_fn(params, x, key=None):
        if key is None or rate == 0.0: return x
        shape = tuple(1 if i in broadcast_dims else s for i, s in enumerate(x.shape))
        keep = random.bernoulli(key, 1.0 - rate, shape)
        return jnp.where(keep, x / (1.0 - rate), 0.0)
    return {}, dropout_fn


def make_linear(key, fan_in, fan_out, act_fn=jax.nn.relu, initializer=jax.nn.initializers.he_normal, bias=True, act=True, dropout=0.0):
    init = initializer()
    params = {}
    params["w"] = init(key, (fan_in, fan_out), jnp.float32)
    if bias: params["b"] = jnp.zeros(fan_out)
    _, drop = make_dropout(None, dropout)
    
    def lin_fn(params, x, key=None):
        x = x@params["w"]
        if bias: x += params["b"]
        if act: x = act_fn(x)
        x = drop({}, x, key=key)
        return x
    
    return params, lin_fn

def make_ffn(key, din, dout, hidden_layer=512, act_fn=jax.nn.relu, initializer=jax.nn.initializers.he_normal, bias=True, dropout=0.0):
    k1, k2 = random.split(key)
    params = {}
    params['Linear_1'], ffn1 = make_linear(k1, din, hidden_layer, act_fn=act_fn, initializer=initializer, bias=bias, act=True, dropout=dropout)
    params['Linear_2'], ffn2 = make_linear(k2, hidden_layer, dout, act_fn=act_fn, initializer=initializer, bias=bias, act=False)
    def ffn_fn(params, x, key=None):
        return ffn2(params['Linear_2'], ffn1(params['Linear_1'], x, key=key))
    return params, ffn_fn


def make_conv2d(key, cho, chi, ks=(3, 3), padding='SAME', strides=(1, 1), act_fn=jax.nn.relu, initializer=jax.nn.initializers.he_normal, bias=True, act=True, dropout=0.0, spatial=True):
    init = initializer(in_axis=1, out_axis=0)
    params = {}
    params["w"] = init(key, (cho, chi, *ks), jnp.float32)
    if bias: params["b"] = jnp.zeros(cho)
    _, drop = make_dropout(None, dropout, broadcast_dims=(2, 3) if spatial else ())
    
    def conv2d_fn(params, x, key=None):
        x = jax.lax.conv_general_dilated(x, params["w"], padding=padding, window_strides=strides)
        if bias: x += params["b"][None, :, None, None]
        if act: x = act_fn(x)
        x = drop({}, x, key=key)
        return x
    
    return params, conv2d_fn

def make_squeeze(key, dims=None):
    
    def squeeze(params, x): 
        if dims is None:
            return x.squeeze()
        return jnp.squeeze(x, axis=dims)
    
    return {}, squeeze

def make_mean(key, dims=1):
    def mean_fn(params, x): return x.mean(axis=dims)
    return {}, mean_fn

def make_layernorm1d(key, num_features, eps=1e-5, offset=True):
    params = {}
    params["scale"] = jnp.ones(num_features)
    if offset: params["offset"] = jnp.zeros(num_features)
    
    def layernorm_fn(params, x):
        mean = jnp.mean(x, axis=-1, keepdims=True)
        var = jnp.var(x, axis=-1, keepdims=True)
        x_norm = (x - mean) / jnp.sqrt(var + eps)
        x = x_norm * params["scale"]
        if offset: x += params["offset"]
        return x
    
    return params, layernorm_fn

def make_layernorm2d(key, num_features, eps=1e-5, offset=True, ndims=4):
    broadcast_dims = tuple(None for i in range(ndims-2))
    axes = tuple(range(1, ndims))
    params = {}
    params["scale"] = jnp.ones(num_features)
    if offset: params["offset"] = jnp.zeros(num_features)
    
    def layernorm2d_fn(params, x):
        mean = jnp.mean(x, axis=axes)[:, None, *broadcast_dims]
        var = jnp.var(x, axis=axes)[:, None, *broadcast_dims]
        x_norm = (x - mean) / jnp.sqrt(var + eps)
        x = x_norm * params["scale"][None, :, *broadcast_dims]
        if offset: x += params["offset"][None, :, *broadcast_dims]
        return x
    
    return params, layernorm2d_fn

def make_sinusoidal_embedding(key=None, d=512, ldmin=10**(-2.5), ldmax=10**(3.3)):
    i = jnp.arange(d // 2)
    lds = 2 * jnp.pi * 1/(ldmin * (ldmax/ldmin)**((2 * i)/(d-2)))

    def sinusoidal_embedding_fn(params, x):
        sine = jnp.sin(lds[None, :] * x[..., None])
        cosine = jnp.cos(lds[None, :] * x[..., None])
        x = jnp.concat((sine, cosine), axis=-1)
        return x
    
    return {}, sinusoidal_embedding_fn

def make_peak_embedding(key, d=512, hidden_layer=512, ldmin=10**(-2.5), ldmax=10**(3.3), act_fn=jax.nn.relu, initializer=jax.nn.initializers.he_normal, bias=True, hidden_dropout=0.0, emb_dropout=0.0):
    params = {}
    keys = random.split(key, 4)
    params['Linear_11'], ln11 = make_linear(keys[0], d, hidden_layer, act_fn=act_fn, initializer=initializer, bias=True, act=True, dropout=hidden_dropout)
    params['Linear_12'], ln12 = make_linear(keys[1], hidden_layer, d, act_fn=act_fn, initializer=initializer, bias=True, act=False)
    params['Linear_21'], ln21 = make_linear(keys[2], d+1, hidden_layer, act_fn=act_fn, initializer=initializer, bias=True, act=True, dropout=hidden_dropout)
    params['Linear_22'], ln22 = make_linear(keys[3], hidden_layer, d, act_fn=act_fn, initializer=initializer, bias=True, act=False, dropout=emb_dropout)
    _, se = make_sinusoidal_embedding(d=d, ldmin=ldmin, ldmax=ldmax)

    def peak_embedding_fn(params, x, key=None):
        k1, k2, k3 = split_key(key, 3)
        mzs = x[..., 0]
        ints = x[..., 1:2]
        mlp1_in = se({}, mzs)
        res1 = ln12(params['Linear_12'], ln11(params['Linear_11'], mlp1_in, key=k1))
        mlp2_in = jnp.concat((res1, ints), axis=-1)
        res2 = ln22(params['Linear_22'], ln21(params['Linear_21'], mlp2_in, key=k2), key=k3)
        return res2

    return params, peak_embedding_fn

def mask_fn(x): return x[..., 0] != 0.0

def make_multi_head_attention(key, nembd, nhead, attention_backend=None, initializer=jax.nn.initializers.he_normal, dropout=0.0):
    params = {}
    keys = random.split(key, 4)
    params["Q"], q_fn = make_linear(keys[0], nembd, nembd, initializer=initializer, bias=False, act=False)
    params["K"], k_fn = make_linear(keys[1], nembd, nembd, initializer=initializer, bias=False, act=False)
    params["V"], v_fn = make_linear(keys[2], nembd, nembd, initializer=initializer, bias=False, act=False)
    params["O"], o_fn = make_linear(keys[3], nembd, nembd, initializer=initializer, bias=False, act=False)
    _, drop = make_dropout(None, dropout)

    if attention_backend == 'tpu_flash': 
        from jax.experimental.pallas.ops.tpu.flash_attention import flash_attention, SegmentIds

    @partial(jax.jit, static_argnames=('sm_scale', 'use_mask'))
    def _flash_attn(q, k, v, mask, sm_scale, use_mask):
        segment_ids = SegmentIds(q=mask, kv=mask) if use_mask else None
        return flash_attention(q, k, v, segment_ids=segment_ids, sm_scale=sm_scale)

    @partial(jax.checkpoint, prevent_cse=False)
    def _remat_attn(wo, q, k, v, mask):
        B, T, nh, H = q.shape
        o_in = jax.nn.dot_product_attention(q, k, v, mask=mask, implementation='xla').reshape(B, T, nh * H)
        return o_fn(wo, o_in)

    @partial(jax.checkpoint, prevent_cse=False)
    def _fp16_attn(wo, q16, k16, v16, mask):
        B, T, nh, H = q16.shape
        o_in = jax.nn.dot_product_attention(q16, k16, v16, mask=mask, implementation='xla').astype(jnp.float32).reshape(B, T, nh * H)
        return o_fn(wo, o_in)

    def multi_head_attention_fn(params, x, mask=None, key=None):
        B, T, C = x.shape
        H = nembd//nhead
        q = q_fn(params["Q"], x).reshape(B, T, nhead, H)
        k = k_fn(params["K"], x).reshape(B, T, nhead, H)
        v = v_fn(params["V"], x).reshape(B, T, nhead, H)
        if attention_backend == 'cudnn':
            if mask is not None: mask = jnp.broadcast_to(mask, (B, 1, T, T))
            o_in = jax.nn.dot_product_attention(q.astype(jnp.bfloat16), k.astype(jnp.bfloat16), v.astype(jnp.bfloat16), mask=mask, implementation="cudnn").astype(jnp.float32).reshape(B, T, C)
            o = o_fn(params["O"], o_in)
        elif attention_backend == 'tpu_flash':
            mask = mask.squeeze(axis=(1, 2)).astype(jnp.int32) if mask is not None else None
            q = q.transpose(0, 2, 1, 3)
            k = k.transpose(0, 2, 1, 3)
            v = v.transpose(0, 2, 1, 3)
            use_mask = mask is not None
            if not use_mask: mask = jnp.zeros((B, T), dtype=jnp.int32)
            o_in = _flash_attn(q, k, v, mask, sm_scale=float(1 / (H ** 0.5)), use_mask=use_mask).transpose(0, 2, 1, 3).reshape(B, T, C)
            o = o_fn(params["O"], o_in)
        elif attention_backend == 'quantize_fp16':
            o = _fp16_attn(params["O"], q.astype(jnp.float16), k.astype(jnp.float16), v.astype(jnp.float16), mask)
        elif attention_backend == 'remat':
            o = _remat_attn(params["O"], q, k, v, mask)
        else:
            o = o_fn(params["O"], jax.nn.dot_product_attention(q, k, v, mask=mask, implementation=attention_backend).reshape(B, T, C))
        return drop({}, o, key=key)

    return params, multi_head_attention_fn

def make_transformer_block(key, nembd, nhead, ffdim=None, attention_backend=None, act_fn=jax.nn.relu, initializer=jax.nn.initializers.he_normal, bias=True, dropout=0.0, hidden_dropout=0.0):
    params = {}
    keys = random.split(key, 3)
    ffdim = ffdim if ffdim else 4 * nembd
    params["MultiHeadAttention"], mha_fn = make_multi_head_attention(keys[0], nembd, nhead, attention_backend=attention_backend, initializer=initializer, dropout=dropout)
    params["LayerNorm_1"], ln1_fn = make_layernorm1d(None, num_features=nembd)
    params["LayerNorm_2"], ln2_fn = make_layernorm1d(None, num_features=nembd)
    params['Linear_1'], ffn1 = make_linear(keys[1], nembd, ffdim, act_fn=act_fn, initializer=initializer, bias=bias, act=True, dropout=hidden_dropout)
    params['Linear_2'], ffn2 = make_linear(keys[2], ffdim, nembd, act_fn=act_fn, initializer=initializer, bias=bias, act=False, dropout=dropout)

    def transformer_block_fn(params, x, mask=None, key=None):
        k1, k2, k3 = split_key(key, 3)
        x = x + mha_fn(params["MultiHeadAttention"], ln1_fn(params["LayerNorm_1"], x), mask=mask, key=k1)
        h = ffn1(params['Linear_1'], ln2_fn(params["LayerNorm_2"], x), key=k2)
        return x + ffn2(params['Linear_2'], h, key=k3)

    return params, transformer_block_fn

def make_spectrum_encoder(key, d=512, ldmin=10**(-2.5), ldmax=10**(3.3), hidden_layer=512, ffdim=512, nhead=32, nlayers=6, act_fn=jax.nn.relu, initializer=jax.nn.initializers.he_normal, attention_backend=None, mask_fn=mask_fn, dropout=0.0, hidden_dropout=0.0, emb_dropout=0.0):
    params = {}
    key, pe_key = random.split(key)
    params["PeakEmbedding"], pe_fn = make_peak_embedding(pe_key, d=d, hidden_layer=hidden_layer, ldmin=ldmin, ldmax=ldmax, act_fn=act_fn, initializer=initializer, hidden_dropout=hidden_dropout, emb_dropout=emb_dropout)
    tb_param_list = []
    for i in range(nlayers):
        key, tb_key = random.split(key)
        p, tb_fn = make_transformer_block(tb_key, d, nhead, ffdim=ffdim, act_fn=act_fn, initializer=initializer, attention_backend=attention_backend, dropout=dropout, hidden_dropout=hidden_dropout)
        tb_param_list.append(p)
    stacked = jax.tree.map(lambda *xs: jnp.stack(xs), *tb_param_list)
    params["TransformerBlocks"] = stacked
    params["LayerNorm"], ln_fn = make_layernorm1d(None, d)

    def spectrum_encoder_fn(params, x, key=None):
        mask = mask_fn(x)[:, None, None, :] if mask_fn else None
        k_pe, k_tb = split_key(key, 2)
        x = pe_fn(params["PeakEmbedding"], x, key=k_pe)
        if key is None:
            x, _ = jax.lax.scan(lambda h, lp: (tb_fn(lp, h, mask), None), x, params["TransformerBlocks"])
        else:
            ks = random.split(k_tb, nlayers)
            x, _ = jax.lax.scan(lambda h, a: (tb_fn(a[0], h, mask, key=a[1]), None), x, (params["TransformerBlocks"], ks))
        x = ln_fn(params["LayerNorm"], x)[:, 0]
        return x

    return params, spectrum_encoder_fn

def make_property_predictor(key, d=512, ldmin=10**(-2.5), ldmax=10**(3.3), hidden_layer=512, ffdim=512, nhead=32, nlayers=6, dout=10, act_fn=jax.nn.relu, initializer=jax.nn.initializers.he_normal, attention_backend=None, bias=True, mask_fn=mask_fn, dropout=0.0, hidden_dropout=0.0, emb_dropout=0.0, head_dropout=0.0):
    params = {}
    keys = random.split(key, num=3)
    params["SpectrumEncoder"], spectrum_encoder_fn = make_spectrum_encoder(keys[0], d=d, ldmin=ldmin, ldmax=ldmax, hidden_layer=hidden_layer, ffdim=ffdim, nhead=nhead, nlayers=nlayers, act_fn=act_fn, initializer=initializer, attention_backend=attention_backend, mask_fn=mask_fn, dropout=dropout, hidden_dropout=hidden_dropout, emb_dropout=emb_dropout)
    params['Linear_1'], ffn1 = make_linear(keys[1], d, hidden_layer, act_fn=act_fn, initializer=initializer, bias=bias, act=True, dropout=head_dropout)
    params['Linear_2'], ffn2 = make_linear(keys[2], hidden_layer, dout, act_fn=act_fn, initializer=initializer, bias=bias, act=False)

    def property_predictor_fn(params, x, key=None):
        k_enc, k_head = split_key(key, 2)
        x = spectrum_encoder_fn(params["SpectrumEncoder"], x, key=k_enc)
        x = ffn2(params['Linear_2'], ffn1(params['Linear_1'], x, key=k_head))
        return x

    return params, property_predictor_fn
